  ('51000000-0000-0000-0000-000000060103', '41000000-0000-0000-0000-000000000601', 'Adding and subtracting', 'Chooses strategies to add and subtract whole numbers and decimals.', 1, NULL, 'MA3-AR-01'),
  ('51000000-0000-0000-0000-000000060102', '41000000-0000-0000-0000-000000000601', 'Multiplying and dividing', 'Chooses strategies to multiply and divide, including decimals.', 2, NULL, 'MA3-MR-01'),
  ('51000000-0000-0000-0000-000000060101', '41000000-0000-0000-0000-000000000601', 'Order of operations', 'Uses brackets, ×, ÷, + and − in the correct order.', 3, 'ma3-order-of-operations', 'MA3-MR-02'),
  ('51000000-0000-0000-0000-000000060204', '41000000-0000-0000-0000-000000000602', 'Decimals', 'Compares and orders decimals to three decimal places.', 1, NULL, 'MA3-RN-02'),
  ('51000000-0000-0000-0000-000000060201', '41000000-0000-0000-0000-000000000602', 'Adding and subtracting fractions', 'Adds and subtracts fractions with the same or related denominators.', 2, 'ma3-add-fractions', 'MA3-RQF-01'),
  ('51000000-0000-0000-0000-000000060202', '41000000-0000-0000-0000-000000000602', 'Fraction of a quantity', 'Finds a fraction of a whole number, such as 3/4 of 20.', 3, 'ma3-fraction-of-quantity', 'MA3-RQF-02'),
  ('51000000-0000-0000-0000-000000060203', '41000000-0000-0000-0000-000000000602', 'Percentages of amounts', 'Finds 10%, 25%, 50% and 75% of amounts, including money.', 4, 'ma3-percentages', 'MA3-RN-03'),
  ('51000000-0000-0000-0000-000000060501', '41000000-0000-0000-0000-000000000605', 'Length and perimeter', 'Converts units of length and works out perimeters.', 1, NULL, 'MA3-GM-02'),
