  ('51000000-0000-0000-0000-000000060503', '41000000-0000-0000-0000-000000000605', 'Area of triangles and parallelograms', 'Uses base and height to find the area of triangles and parallelograms.', 3, NULL, 'MA3-2DS-03'),
  ('51000000-0000-0000-0000-000000060504', '41000000-0000-0000-0000-000000000605', 'Volume and capacity', 'Works out volumes of prisms and links cubic centimetres to millilitres.', 4, NULL, 'MA3-3DS-02'),
  ('51000000-0000-0000-0000-000000060505', '41000000-0000-0000-0000-000000000605', 'Mass', 'Measures and converts mass in grams, kilograms and tonnes.', 5, NULL, 'MA3-NSM-01'),
  ('51000000-0000-0000-0000-000000060506', '41000000-0000-0000-0000-000000000605', 'Time', 'Reads timetables, 24-hour time and Australian time zones.', 6, NULL, 'MA3-NSM-02'),
  ('51000000-0000-0000-0000-000000060301', '41000000-0000-0000-0000-000000000603', 'Angles', 'Names types of angles and uses angle facts to find unknown angles.', 1, NULL, 'MA3-GM-03'),
  ('51000000-0000-0000-0000-000000060302', '41000000-0000-0000-0000-000000000603', 'Classifying shapes', 'Classifies triangles and quadrilaterals by their properties.', 2, NULL, 'MA3-2DS-01'),
  ('51000000-0000-0000-0000-000000060303', '41000000-0000-0000-0000-000000000603', 'Prisms, pyramids and nets', 'Visualises 3D objects from different views and matches them to their nets.', 3, NULL, 'MA3-3DS-01'),
  ('51000000-0000-0000-0000-000000060304', '41000000-0000-0000-0000-000000000603', 'Coordinates', 'Plots and reads points in all four quadrants.', 4, NULL, 'MA3-GM-01'),
