  ('51000000-0000-0000-0000-000000031501', '41000000-0000-0000-0000-000000000315', 'Story writing', 'Story structure, describing words, dialogue and punctuation.', 1, NULL, 'EN2-CWT-01'),
  ('51000000-0000-0000-0000-000000031502', '41000000-0000-0000-0000-000000000315', 'Information texts', 'Headings, facts, instructions and joining words.', 2, NULL, 'EN2-CWT-02'),
  ('51000000-0000-0000-0000-000000031503', '41000000-0000-0000-0000-000000000315', 'Persuasive texts', 'Opinions, reasons and persuasive words.', 3, NULL, 'EN2-CWT-03'),
