  ('51000000-0000-0000-0000-000000041104', '41000000-0000-0000-0000-000000000411', 'Information texts', 'Headings, facts, procedures, reports and joining words.', 4, NULL, 'EN2-CWT-02'),
  ('51000000-0000-0000-0000-000000041105', '41000000-0000-0000-0000-000000000411', 'Persuasive features', 'Opinions, reasons, persuasive words and connectives.', 5, NULL, 'EN2-CWT-03'),
  ('51000000-0000-0000-0000-000000041201', '41000000-0000-0000-0000-000000000412', 'Nouns, verbs and adjectives', 'Identifies nouns, verbs and adjectives in sentences.', 1, NULL, NULL),
  ('51000000-0000-0000-0000-000000041202', '41000000-0000-0000-0000-000000000412', 'Building sentences', 'Puts words and events in a sensible order.', 2, NULL, NULL),
  ('51000000-0000-0000-0000-000000041301', '41000000-0000-0000-0000-000000000413', 'Spelling patterns', 'Uses sounds, patterns and word parts to spell words.', 1, NULL, 'EN2-SPELL-01'),
