  ('51000000-0000-0000-0000-000000051101', '41000000-0000-0000-0000-000000000511', 'Spelling with prefixes and suffixes', 'Uses base words, prefixes, suffixes and word origins to spell.', 1, 'en3-spelling', 'EN3-SPELL-01'),
  ('51000000-0000-0000-0000-000000051201', '41000000-0000-0000-0000-000000000512', 'Precise vocabulary', 'Chooses precise words and understands figurative language.', 1, 'en3-vocabulary', 'EN3-VOCAB-01'),
  ('51000000-0000-0000-0000-000000051301', '41000000-0000-0000-0000-000000000513', 'Inference and author''s purpose', 'Infers meaning, identifies the author''s purpose and evaluates texts.', 1, 'en3-comprehension', 'EN3-RECOM-01'),
  ('51000000-0000-0000-0000-000000051302', '41000000-0000-0000-0000-000000000513', 'Character, imagery and symbol', 'Explains how writers use character, imagery and symbols to share ideas.', 2, NULL, 'EN3-UARL-01'),
  ('51000000-0000-0000-0000-000000051303', '41000000-0000-0000-0000-000000000513', 'Genre, theme and point of view', 'Compares genres and themes, and how a writer''s point of view shapes a text.', 3, NULL, 'EN3-UARL-02'),
  ('51000000-0000-0000-0000-000000051401', '41000000-0000-0000-0000-000000000514', 'Apostrophes', 'Uses apostrophes for contractions and to show belonging.', 1, NULL, NULL),
  ('51000000-0000-0000-0000-000000051501', '41000000-0000-0000-0000-000000000515', 'Writing skills', 'Text features, complex sentences, punctuation and cohesion across text types.', 1, NULL, 'EN3-CWT-01'),
  ('51000000-0000-0000-0000-000000061101', '41000000-0000-0000-0000-000000000611', 'Writing to inform', 'Writes an organised informative text with topic sentences and facts.', 1, 'en3-informative', 'EN3-CWT-01'),
  ('51000000-0000-0000-0000-000000061102', '41000000-0000-0000-0000-000000000611', 'Persuasive essays', 'Writes a persuasive text with an introduction, arguments, evidence and conclusion.', 2, 'en3-persuasive', 'EN3-CWT-01'),
  ('51000000-0000-0000-0000-000000061103', '41000000-0000-0000-0000-000000000611', 'Writing skills', 'Text features, complex sentences, punctuation and cohesion across text types.', 3, NULL, 'EN3-CWT-01'),
  ('51000000-0000-0000-0000-000000061201', '41000000-0000-0000-0000-000000000612', 'Figurative language', 'Recognises similes, metaphors, personification and onomatopoeia.', 1, NULL, NULL),
  ('51000000-0000-0000-0000-000000061301', '41000000-0000-0000-0000-000000000613', 'Spelling', 'Uses roots, prefixes, suffixes and patterns to spell words.', 1, NULL, 'EN3-SPELL-01'),
